int imbalanceSignal(long long Qb, long long Qa){
    long long tot = Qb + Qa;
    if (tot == 0) return 0;
    double I = (double)Qb / tot;
    if (I > 0.66) return +1;
    if (I < 0.34) return -1;
    return 0;
}

def imbalance_signal(qb, qa):
    tot = qb + qa
    if tot == 0:
        return 0
    I = qb / tot
    if I > 0.66:
        return 1
    if I < 0.34:
        return -1
    return 0
